export function formatProviderConnectError(
  displayName: string,
  error: RuntimeProviderManagementErrorDto
): string {
  const normalizedMessage = error.message.toLowerCase();
  if (error.message.includes('V2 connection cannot replace an existing OpenCode credential.')) {
    return `${displayName} already has a saved API key. Use the existing connection. Replacing this key would also change your OpenCode V1 connection.`;
  }

  const invalidApiKey =
    /\binvalid[\s_-]+api[\s_-]*key\b/.test(normalizedMessage) ||
    /\bapi[\s_-]*key\s+(?:is\s+)?(?:invalid|expired|revoked)\b/.test(normalizedMessage);
  if (invalidApiKey) {
    return `${displayName} rejected this API key. The new credential was not kept. Copy the key from the correct account or subscription plan, then try again.`;
  }
  if (
    normalizedMessage.includes('access denied by security policy') ||
    normalizedMessage.includes('forbidden')
  ) {
    return `${displayName} rejected the verification request because of an account or security policy. The new credential was not kept. Check the key permissions and account restrictions, then try again.`;
  }
  if (error.code === 'auth-failed') {
    return `${displayName} could not verify this credential with a real model request. The new credential was not kept.\n${error.message}`;
  }
  return error.message;
}

if (response.error) {
  const cancelled = recordUnsuccessfulConnection(response.error);
  if (!isProjectContextCurrent(projectContext)) {
    return null;
  }
  setSetupSubmitError(
    cancelled
      ? formatProviderConnectCancellation(form.displayName)
      : formatProviderConnectError(form.displayName, response.error)
  );
  setSetupSubmitErrorDiagnostics(
    cancelled ? null : getProviderConnectErrorDiagnostics(response.error)
  );
  return cancelled ? { status: 'cancelled', verifiedModelId: null } : null;

if (!connectedProvider) {
  const cancelled = recordUnsuccessfulConnection(null);
  if (!isProjectContextCurrent(projectContext)) {
    return null;
  }
  setSetupSubmitError(
    cancelled
      ? formatProviderConnectCancellation(form.displayName)
      : `${form.displayName} did not confirm the connection. Your current credential was not changed. Try again or refresh provider status.`
  );
  setSetupSubmitErrorDiagnostics(null);
  return cancelled ? { status: 'cancelled', verifiedModelId: null } : null;

export interface RuntimeProviderManagementErrorDto {
  code: RuntimeProviderManagementErrorCodeDto;
  message: string;
  recoverable: boolean;
  diagnostics?: RuntimeProviderManagementErrorDiagnosticsDto | null;
}

private async run(target: CapturedProviderManagement, input: CredentialInput, selection: AuthSelection): Promise<void> {
  const pending = managementValue(await target.request('credential.pending', { providerId: input.providerId }));
  if (!pending || typeof pending !== 'object' || Array.isArray(pending) ||
      !('generation' in pending) || !['v1', 'v2'].includes(String(pending.generation)) ||
      !('receipt' in pending)) throw new Error('Original credential owner unavailable');
  if (pending.generation === 'v2' && (input.kind !== 'credential.set' || input.metadata && Object.keys(input.metadata).length ||
      selection.authMethodIndex != null || selection.authOptionId != null && selection.authOptionId !== 'api:native'))
    throw new Error('This OpenCode V2 credential action is unavailable');
  let commandId: string = randomUUID();
  const retained = pending.receipt !== null;
  if (retained) commandId = receipt({ ok: true, value: pending.receipt }, target, input).commandId;
  let raw: unknown;
  try {
    // Existing intent checks the submitted fingerprint and only reads its original
    // receipt. A new UUID reaches native work only after the Host durably claims it.
    raw = await target.request(retained ? 'credential.resume' : 'credential', { ...input, commandId });
  } catch {
    // A transport failure is neither rejection nor permission to submit another key.
    raw = await target.request('credential.resume', { ...input, commandId });
  }
  const result = receipt(raw, target, input, commandId);
  if (result.phase === 'held' && result.reason === 'verification-rejected')
    throw new CapturedCredentialVerificationRejected('The saved key could not verify a model');
  if (result.phase !== 'completed')
    throw new Error('The original credential operation or model verification remains unconfirmed');
}

try {
  if (
    !captured.providerId ||
    captured.providerId.length > 256 ||
    (key !== undefined && (!key.trim() || key.length > 8192 || /[\0\r\n]/.test(key)))
  )
    throw new Error('Invalid credential');
  const target = await capture(captured);
  await credentials.execute(target, {
    kind: key === undefined ? 'credential.forget' : 'credential.set',
    providerId: captured.providerId,
    ...(key === undefined ? {} : { key }),
    ...(capturedMetadata ? { metadata: capturedMetadata } : {}),
  }, capturedSelection);
  // Refresh against the same capture, never a new default/current context.
  return {
    schemaVersion: 1,
    runtimeId: 'opencode',
    provider: connection(
      selected(await catalog(target, captured.providerId), captured.providerId)
    ),
  };
} catch (error) {
  if (error instanceof CapturedCredentialVerificationRejected) return {
    schemaVersion: 1, runtimeId: 'opencode', error: { code: 'auth-failed',
      message: 'The key was saved, but the model check failed. Check the key and connect again.',
      recoverable: true },
  };
  return unavailable(error);

  check();
  let saved: OpenCodeV2CredentialProgress | undefined;
  const selectedModel = await host.keyOperation(command.providerId, async native => {
    check();
    const before = await native.read();
    check();
    if (!before.plainKey || before.connections.length) { rejected = true; return held(); }
    saved = { phase: 'key-intent', integrationId: native.integrationId,
      nativeNamespace: openCodeV2KeyNamespace(profile, command.commandId), beforeAuthDigest: auth.digest };
    progress(saved);
    const connected = await native.connectKey(command.key);
    check();
    saved = { ...saved, phase: 'key-connected', credentialId: connected.credentialId };
    progress(saved);
    try { auth = publication.publish(); }
    catch (error) {
      // This exact client alone observed empty-before/single-after ownership.
      try { await native.rollbackOwnedKey(); } catch { cleanupUnknown = true; }
      throw error;
    }
    saved = { ...saved, phase: 'key-published', authDigest: auth.digest };
    progress(saved);
    const catalog = await native.readCatalog();
    check();
    const models = catalog.models.filter(model => model.enabled);
    const chosen = models.find(model => profile.nativeModel!.providerId === command.providerId &&
      model.id === profile.nativeModel!.modelId) ?? models.find(model => model.supportsTools);
    if (!catalog.provider || !chosen) return held();
    return chosen.id;
  });
  if (!await host.close()) { cleanupUnknown = true; held(); }
  check();
  const verification = { commandId: 'connect-verify-' + managementDigest(command.commandId).slice(0, 48),
    modelId: command.providerId + '/' + selectedModel };
  saved = { ...saved!, phase: 'probe-intent', verification };
  progress(saved);
  const probeProfile = selectOpenCodeV2ManagementModel(profile,
    { providerId: command.providerId, modelId: verification.modelId });
  probe = createOpenCodeV2ModelProbe(probeProfile, { ...verification,
    profileId: profile.profileId, configRevision: profile.configRevision, providerId: command.providerId },
  current, options.processCustody ? { processCustody: options.processCustody } : {});
  ok = await probe.run(abort.signal);
  check();
  if (!await probe.close()) { cleanupUnknown = true; held(); }
  progress({ ...saved, phase: 'probe-completed', verification: { ...verification, ok } });
  // Only a qualified failed terminal permits a later explicit Connect. A
  // boolean false or confirmed process cleanup alone cannot permit replay.
  rejected = !ok && probe.wasRejected();
} catch { ok = false; }
const settled = await close();
return { ok, settled, ...(rejected && settled ? { rejected: true } : {}) };

  this.options.assertCurrent();
  assertManagementTarget(saved, this.options.select(command.profileId, command.configRevision));
  saved.phase = result.ok && settled ? 'completed' : 'held';
  saved.resourceHeld = !settled;
  const completedAt = Date.now();
  saved.finishedAtMs = this.finishTime(target.resourceId);
  if (!result.ok && settled && 'rejected' in result && result.rejected === true)
    saved.terminalRejection = true;
  if (saved.phase === 'completed' && command.kind === 'credential.refresh')
    saved.refreshCompletedAtMs = reused?.refreshCompletedAtMs ?? completedAt;
  this.options.store.write(saved);
  return this.receipt(saved);
} catch {
  // A lost response/publication is UNKNOWN. Never replay the mutation under a new process.
  saved.phase = 'held';
  delete saved.refreshCompletedAtMs;
  delete saved.terminalRejection;
  saved.resourceHeld = !settled;
  try {
    this.options.assertCurrent();
    this.options.store.write(saved);
  } catch {
    settled = false;
  }
  return this.receipt(saved);
} finally {
  this.fence.release(target.resourceId, command.commandId, settled);

private receipt(saved: StoredCredentialCommand): CredentialCommandReceipt {
  return {
    commandId: saved.commandId,
    profileId: saved.profileId,
    configRevision: saved.configRevision,
    kind: saved.kind,
    providerId: saved.providerId,
    phase: saved.phase === 'completed' ? 'completed' : 'held',
    ...(saved.terminalRejection && saved.openCodeV2?.phase === 'probe-completed' &&
      saved.openCodeV2.verification?.ok === false ? { reason: 'verification-rejected' as const } : {}),
  };

/** Private authorization from this owner's rejected publication, never a caller-supplied overwrite flag. */
private replaceableV2Auth(profile: OpenCodeManagementProfile, providerId: string, currentCommandId?: string): string | undefined {
  this.assertCurrent();
  const target = this.credentialTarget(profile);
  let latest: StoredCredentialCommand | undefined;
  for (const row of this.store.list()) {
    if ((row.kind !== 'credential.set' && row.kind !== 'credential.forget' && row.kind !== 'credential.refresh') ||
        row.providerId !== providerId || row.resourceId !== target.resourceId || row.commandId === currentCommandId) continue;
    const original = this.profiles.get(row.profileId);
    if (!original || original.configRevision !== row.configRevision) throw new ManagementCommandError('held');
    assertManagementTarget(row, this.credentialTarget(original));
    // A source revision cannot turn an unknown original intent into a new Connect, even with the same key.
    if (row.resourceHeld || row.phase !== 'completed' && row.terminalRejection !== true)
      throw new ManagementCommandError('conflict');
    // A confirmed rejection before publication changes neither key nor the previous publication's authority.
    if (row.phase !== 'completed' && !row.openCodeV2?.authDigest) continue;
    if (row.finishedAtMs === undefined) throw new ManagementCommandError('held');
    if (latest?.finishedAtMs === row.finishedAtMs) throw new ManagementCommandError('held');
    if (!latest || row.finishedAtMs > latest.finishedAtMs!) latest = row;
  }
  if (latest?.kind !== 'credential.set' || latest.terminalRejection !== true || latest.resourceHeld ||
      latest.openCodeV2?.phase !== 'probe-completed' || latest.openCodeV2.verification?.ok !== false ||
      this.profiles.get(latest.profileId)?.nativeGeneration !== 'v2') return undefined;
  const auth = new OpenCodeV2CredentialScope(profile, providerId, () => {
    this.assertCurrent(); return true;
  }).capture();
  // The existing digest binds account/provider, both captured roots, auth directories and the selected key.
  return auth.present && auth.digest === latest.openCodeV2.authDigest ? auth.digest : undefined;
}

private connectedV2(profile: OpenCodeManagementProfile, providerId: string, authDigest: string): boolean {
  const { latest, pending } = this.v2CredentialState(profile, providerId);
  return !pending && latest?.phase === 'completed' && latest.openCodeV2?.phase === 'probe-completed' &&
    latest.openCodeV2.verification?.ok === true && latest.openCodeV2.authDigest === authDigest;

